<?php
namespace App\Services;
use App\Models\Ingredient;use App\Models\StockBalance;use App\Models\StockWaste;use App\Models\StockWasteItem;use App\Models\Unit;use Illuminate\Contracts\Pagination\LengthAwarePaginator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class StockWasteItemService
{
 public function __construct(private readonly UnitConversionService $units){}
 public function getAll(?string $s=null,?int $id=null):LengthAwarePaginator{return StockWasteItem::query()->with(['stockWaste.stockLocation','ingredient.baseUnit','unit'])->when($id,fn(Builder $q)=>$q->where('stock_waste_id',$id))->when($s,fn(Builder $q)=>$q->whereHas('ingredient',fn(Builder $i)=>$i->where('name','like',"%$s%")->orWhere('code','like',"%$s%")))->orderByDesc('stock_waste_id')->orderBy('id')->paginate(15)->withQueryString();}
 public function options():array{return ['wastes'=>StockWaste::query()->where('status','draft')->with('stockLocation')->orderByDesc('waste_date')->get(),'ingredients'=>Ingredient::query()->with('baseUnit')->orderBy('name')->get(['id','code','name','base_unit_id']),'units'=>Unit::query()->orderBy('dimension')->orderBy('name')->get(['id','name','abbreviation','dimension'])];}
 public function create(array $d):StockWasteItem{return DB::transaction(function()use($d):StockWasteItem{$w=StockWaste::query()->whereKey($d['stock_waste_id'])->lockForUpdate()->firstOrFail();$this->draft($w);$i=Ingredient::query()->with('baseUnit')->findOrFail($d['ingredient_id']);$u=Unit::query()->findOrFail($d['unit_id']);$f=$this->units->conversionFactor($u,$i->baseUnit);$b=StockBalance::query()->where('ingredient_id',$i->id)->where('stock_location_id',$w->stock_location_id)->first();$cost=(float)($b?->average_unit_cost??0)*$f;$this->ensureNoDuplicate($w,$i->id);return $w->items()->create([...$d,'unit_cost'=>round($cost,6),'total_cost'=>round((float)$d['quantity']*$cost,2)]);});}
 public function update(StockWasteItem $item,array $d):StockWasteItem{return DB::transaction(function()use($item,$d):StockWasteItem{$old=StockWaste::query()->whereKey($item->stock_waste_id)->lockForUpdate()->firstOrFail();$w=StockWaste::query()->whereKey($d['stock_waste_id'])->lockForUpdate()->firstOrFail();$this->draft($old);$this->draft($w);$i=Ingredient::query()->with('baseUnit')->findOrFail($d['ingredient_id']);$u=Unit::query()->findOrFail($d['unit_id']);$f=$this->units->conversionFactor($u,$i->baseUnit);if($item->stock_waste_id!=$w->id||$item->ingredient_id!=$i->id)$this->ensureNoDuplicate($w,$i->id,$item->id);$b=StockBalance::query()->where('ingredient_id',$i->id)->where('stock_location_id',$w->stock_location_id)->first();$cost=(float)($b?->average_unit_cost??0)*$f;$item->update([...$d,'unit_cost'=>round($cost,6),'total_cost'=>round((float)$d['quantity']*$cost,2)]);return $item->refresh();});}
 public function delete(StockWasteItem $item):bool{return DB::transaction(function()use($item):bool{$w=StockWaste::query()->whereKey($item->stock_waste_id)->lockForUpdate()->firstOrFail();return $w->status==='draft'&&(bool)$item->delete();});}
 private function ensureNoDuplicate(StockWaste $w,int $id,?int $except=null):void{if($w->items()->where('ingredient_id',$id)->when($except,fn(Builder $q)=>$q->where('id','!=',$except))->exists())throw ValidationException::withMessages(['ingredient_id'=>'This ingredient is already in the waste record.']);}
 private function draft(StockWaste $w):void{if($w->status!=='draft')throw ValidationException::withMessages(['stock_waste_id'=>'Waste lines can only be changed while the record is a draft.']);}
}
